UPDATE courses SET
    course_description = '<p>Are you looking to launch your career in the justice and/or law enforcement fields? With the CQU Diploma of Justice Studies (10972NAT), you will gain the skills and knowledge to achieve that goal.</p><p>The Diploma of Justice Studies is the ideal course to provide you with the skills and knowledge to launch your career in a range of justice and/or law enforcement fields.</p><p>The course provides learners with the specialist skills and knowledge required to perform the following duties and functions:</p><p>This is a nationally recognised accredited course.</p><p>This is a nationally recognised course.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 35250,
    onshore_tuition_fee = 37500,
    entry_requirements = '<p>Completion of the bksb (Basic Key Skills Builder) online literacy, numeracy and digital literacy assessment prior to enrolment, unless the student has completed an equal or higher level course.</p><p>What is the purpose of bksb? </p><p>The bksb is an approved online review tool that will give the student a level for their English (literacy) and Maths (numeracy) levels, and can also help to identify any skill gaps or areas that the student might need additional support in.</p><p>It is beneficial for those seeking entry into the Diploma of Justice Studies to satisfy at least one of the entry requirements provided below:</p>',
    apply_form = 'https://www.cqu.edu.au/courses/cm76/diploma-of-indigenous-entrepreneurship-and-innovation',
    updated_at = NOW()
WHERE cricos_course_code = '084541J';
