UPDATE courses SET
    course_description = '<p>Study the Bachelor of Occupational Therapy (Honours) and kick-start your career as an Occupational Therapist – a rewarding career that allows you to work with people experiencing barriers in their everyday lives as the result of impairment, disability or disadvantage.</p><p>The Bachelor of Occupational Therapy (Honours) at CQUniversity equips you with practical skills, enabling you to use specific activities to help patients participate in life roles.</p><p>The course is designed to ensure you are equipped with an underpinning knowledge in professional practice, human body systems, psychology and contemporary healthcare.</p><p>Your education and training will include occupational therapy courses covering a wide range of practice contexts, and you will develop highly-desired skills in areas such as assessment, service development, evaluation and critical thinking, enabling you to graduate work-ready.</p><p>The course has a strong focus on practical learning experiences, and you will benefit from industry placements across a range of practice areas, including the purpose-built Allied Health Clinic at CQUniversity Rockhampton.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 170400,
    onshore_tuition_fee = 42072,
    apply_form = 'https://www.cqu.edu.au/courses/cb84/bachelor-of-occupational-therapy-honours',
    updated_at = NOW()
WHERE cricos_course_code = '075754D';
UPDATE courses SET
    course_description = '<p>Have a positive influence on the health and wellbeing of people through movement and study the Bachelor of Physiotherapy (Honours) at CQU to develop the knowledge and skills required to practice as a Physiotherapist. Accredited by the Australian Physiotherapy Board of Australia, the course features extensive real-world learning in purpose-built physiotherapy labs and professional clinical practice placements.</p><p>Physiotherapy is a healthcare profession focussed on human function and movement. Physiotherapists use a range of techniques to treat patients, including:</p><p>Through this course, you will develop the essential skills required to assess, treat and manage people of all ages and with musculoskeletal, neurological and cardiorespiratory injuries or diseases.</p><p>You''''ll learn from an experienced physiotherapy academic team and gain relevant industry experience through clinical placements. Upon completion, you''''ll be equipped with the practical skills and knowledge to excel in a wide range of physiotherapy roles. </p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 170400,
    onshore_tuition_fee = 42072,
    apply_form = 'https://www.cqu.edu.au/courses/cb85/bachelor-of-physiotherapy-honours',
    updated_at = NOW()
WHERE cricos_course_code = '075753E';
UPDATE courses SET
    course_description = '<p>Take the first step into an exciting new career in Podiatry by enrolling into the Bachelor of Podiatry (Honours) at CQUniversity.</p><p>Podiatrists are in-demand health professionals who deal with the prevention, diagnosis, treatment, and rehabilitation of medical and surgical conditions of the feet and the lower limb. </p><p>In this course, you will study a broad range of discipline-specific content taught by a range of industry experts, including anatomy and physiology, biomechanics, pharmacology, musculoskeletal and sports podiatry, medical imaging, the high-risk foot, paediatrics, and gerontology. You will also learn to safely and effectively prescribe and inject local anaesthetic and perform minor surgical procedures. </p><p>Practical learning experiences are integral to the course, and you will benefit from completing clinical placements at the purpose-built Allied Health Clinic at CQUniversity in Rockhampton, as well as in a variety of external clinical settings, so you can put your learning into practice and gain real-life experience.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 167040,
    onshore_tuition_fee = 42072,
    apply_form = 'https://www.cqu.edu.au/courses/cb86/bachelor-of-podiatry-honours',
    updated_at = NOW()
WHERE cricos_course_code = '075755C';
