UPDATE courses SET
    course_description = '<p>If you are looking to upskill, or are a tradesperson wanting to enhance your qualifications to a paraprofessional level, the Associate Degree of Building Surveying is an ideal course. </p><p>You will develop skills that are highly desired by employers across a range of areas such as building legislation and auditing, fire safety design and inspection procedures, construction and building materials. </p><p>Learn directly from professionals working in building and construction to gain up-to-date skills and benefit from the flexibility of studying online and part-time alongside your current role. This flexibility will enable you to work in the industry while you study and apply what you are learning in a professional setting.<br/><br/>This course will teach you how to assess building documentation for code and standards compliance and inspect staged works for domestic and residential buildings including class 1 to 10 buildings, not exceeding two stories in height and a total floor area of 500 square metres, as defined by the Building Code of Australia (BCA). Upon completion of this course, you will fulfil the educational requirements for a Level 3 licence by the Australian Institute of Building Surveyors (AIBS) and have the skills and qualification to pursue a career as an Assistant Building Surveyor.<br/><br/>To grow your expertise further and become a building surveyor, this course provides you an ideal pathway into the <a href="/courses/699798/bachelor-of-building-surveying-and-certification-honours">Bachelor of Building Surveying and Certification (Honours)</a>. </p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 67590,
    onshore_tuition_fee = 21100,
    apply_form = 'https://www.cqu.edu.au/courses/cb99/associate-degree-of-building-surveying',
    updated_at = NOW()
WHERE cricos_course_code = '075465B';
UPDATE courses SET
    course_description = '<p>Influence the next generation and guide young people to learn and grow. The Bachelor of Education (Primary) provides you with the qualifications to teach in primary schools from foundation year to Year 6.</p><p>Register for our <a href="/events/1279530/education-open-day-webinar">Education Webinar</a> on Monday 24th August</p><p>This course is an initial teacher education course and qualifies you for professional registration which is administered in Queensland by the Queensland College of Teachers. You will demonstrate evidence of meeting the Australian Professional Standards for Teachers (Graduate career stage) throughout your course.</p><p>On successful completion, you will be eligible for employment in primary school contexts throughout Australia.</p><p>In addition to building the professional knowledge and skills required to teach effectively, the course is designed to foster dispositions for engaging in and contributing to the teaching profession through a commitment to ongoing professional learning.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 129600,
    onshore_tuition_fee = 19200,
