UPDATE courses SET
    course_description = '<p>Prepare for a diverse career working as a professional engineer across various industries, locally, nationally and internationally, with CQUniversity''''s Bachelor of Engineering (Honours). You will have the choice to major in traditional engineering disciplines and specialisation options that will prepare you for emerging specialist fields of engineering.</p><p>Register for our <a href="/events/1211399/engineering-open-day-webinar">Engineering Webinar</a> on Wednesday 2nd September</p><p>The Bachelor of Engineering (Honours) develops your problem-solving, teamwork and communication skills and incorporates project-based learning so you can graduate work-ready.</p><p>The first year of your studies provides a general understanding of engineering, allowing you to experience each different engineering area before you choose a particular path to follow, with majors available in:</p><p>Learn more about each major in the Structure &amp; Availability section below.</p>',
    course_duration_per_week = 260,
