UPDATE courses SET
    course_description = '<p>With extensive work-integrated learning opportunities and 48 weeks of paid industry placement, our Bachelor of Engineering (Honours) and Diploma of Professional Practice (Co-op Engineering) provides you with vast opportunities to gain real-world experience to prepare you for your career as a professional engineer.</p><p>Register for our <a href="/events/1211399/engineering-open-day-webinar">Engineering Webinar</a> on Wednesday 2nd September</p><p>The Bachelor of Engineering (Honours) and Diploma of Professional Practice (Co-op Engineering) allows you to gain hands-on experience in a professional industry environment, being paid while you learn. The course strongly focuses on contextual learning and promoting sustainable development so that you will apply theory to authentic scenarios throughout your course.</p><p>In your first year, you will develop skills in problem-solving, teamwork and professional practice together with learning foundation technical content. By the end of your first year, you will have experienced many engineering projects which will assist you in deciding which engineering discipline and course major you wish to pursue. Your choice of major includes:</p><p>Featuring 48 weeks of paid work placement and project-based learning, you will develop the professional skills required to work as an Engineer and graduate with one year of industry experience.</p>',
    course_duration_per_week = 234,
    offshore_tuition_fee = 202095,
    onshore_tuition_fee = 40500,
