    updated_at = NOW()
WHERE cricos_course_code = '084211E';
UPDATE courses SET
    course_description = '<p>If you are seeking a career in accounting, then the Graduate Certificate in Accounting is a great option for you. You will develop business and accounting skills in line with requirements from the major Australian professional accounting bodies.</p><p>CQUniversity''''s Graduate Certificate in Professional Accounting is excellent preparation to develop a career in accounting.<br/><br/>In this course, you will begin to develop business and accounting skills in line with requirements from the major Australian professional accounting bodies.<br/><br/>If you are a postgraduate student wanting to develop a career in accounting but do not meet the criteria for the <a href="https://www.cqu.edu.au/courses/699790/master-of-professional-accounting">Master of Professional Accounting</a> you may consider enrolling in this course. Upon successful completion of this course, you will be allowed to enrol in the <a href="https://www.cqu.edu.au/courses/699745/graduate-diploma-of-professional-accounting">Graduate Diploma of Professional Accounting</a> and will receive credit for the units completed in the Graduate Certificate.</p>',
    course_duration_per_week = 26,
    offshore_tuition_fee = 18360,
