UPDATE courses SET
    course_description = '<p>Study the Bachelor of Psychological Science (Honours) to become eligible for provisional registration as a psychologist in Australia.</p><p>Register for our <a href="/events/1154120/psychology-open-day-webinar">Psychology Webinar</a> on Tuesday 25th August</p><p>The Bachelor of Psychological Science (Honours) is designed for graduates who wish to become eligible for provisional registration as a Psychologist within Australia. The course is accredited by the Australian Psychology Accreditation Council (APAC) on the basis that it meets all APAC Accreditation Standards for a fourth-year sequence of study in psychology.</p><p>To gain entry into this course, you must have completed an accredited three-year course in psychology within the past 10 years, which includes foundational competencies (as specified by the APAC) and successful completion of year three advanced research methods and statistics.</p><p>During your course, you will be introduced to applied and professional uses of psychology as well as professional ethics and an appreciation of the social and cultural contexts of psychological research and professional practice. You will also undertake advanced research training and have the opportunity to conduct your own original piece of research that may lead to publication in a professional journal. </p>',
    course_duration_per_week = 234,
    offshore_tuition_fee = 110160,
    onshore_tuition_fee = 78300,
    apply_form = 'https://www.cqu.edu.au/courses/cl51/bachelor-of-laws-and-bachelor-of-science-psychology',
