UPDATE courses SET
    course_description = '<p>The CQUniversity Graduate Certificate in Business Administration provides you with opportunities to study contemporary management practices. Advance your career with this degree, or upon completion further your studies with the Graduate Diploma of Business Administration, the Master of Business Administration or other Masters courses at CQUniversity.</p><p>The Graduate Certificate in Business Administration will provide you with opportunities to study a broad range of topics relating to aspects of organisational management. You will develop the creative, analytical and interpersonal capabilities crucial for successful business leadership. The Graduate Certificate in Business Administration allows articulation into the <a href="https://www.cqu.edu.au/courses/699778/graduate-diploma-of-business-administration">Graduate Diploma of Business Administration</a>, the <a href="https://www.cqu.edu.au/courses/699969/master-of-business-administration">Master of Business Administration (MBA)</a> or other Masters courses depending on your previous work experience and study.</p>',
