    course_description = '<p>The Doctor of Philosophy (PhD) is a course of supervised research and study leading to the submission of a thesis which makes a significant original contribution to knowledge. </p><p>The course is governed by the <a href="https://delivery-cqucontenthub.stylelabs.cloud/api/public/content/research-higher-degree-course-rules.pdf">Research Higher Degree Course Rules</a> which provide details regarding all aspects of admission, progression, submission and examination of your thesis.</p><p>Interested in speaking to someone about the Doctor of Philosophy? <a href="/research/research-higher-degrees/ask-a-question">Book a call back today</a>.</p>',
