UPDATE courses SET
    course_description = '<p>The Master of Nutrition and Dietetics is designed to meet workforce needs, equipping you with the knowledge, skills, and attributes required to succeed as a dietitian in regional, rural, or remote Australia.</p><p>Using the latest evidence, you will be prepared to deliver generalist, relationship-focused dietetic care across the lifespan to individuals, groups, and communities. You will develop the skills to navigate complex health and social systems to provide safe and ethical services across the broad landscape of dietetic practice. </p><p>During your studies, you will be supported to develop culturally responsive practice, team communication, clinical reasoning, critical thinking, counselling and behaviour change techniques, as well as digital literacy, leadership, advocacy, and management skills.</p>',
    course_duration_per_week = 234,
    offshore_tuition_fee = 48000,
    onshore_tuition_fee = 52200,
    apply_form = 'https://www.cqu.edu.au/courses/cm61/bachelor-of-nutrition--master-of-nutrition-and-dietetics',
    updated_at = NOW()
