UPDATE courses SET
    course_description = '<p>If you want to make a difference and become an advocate for change CQU''''s innovative Master of Social Work (Qualifying) provides a unique opportunity to engage with cutting‑edge teaching methods and transformative learning experiences.</p><p>Elevate your career with the Master of Social Work (Qualifying). This program is designed to cultivate highly skilled, ethical, and competent social work practitioners ready to make a positive impact in diverse communities. Integrating theory and hands-on practice will give you the advanced knowledge required for effective social work in complex, real-world settings.</p><p>As a student, you will develop critical thinking and a deep understanding of social justice, diversity, and ethical practice. The course emphasises the importance of research-driven approaches and encourages creativity and initiative, particularly during field education placements. You''''ll explore key issues such as the influence of the environment on health and well-being, the dynamics of social and structural inequality, and the different approaches to understanding disability, trauma, and mental health.</p><p>Graduates will be equipped with versatile skills to work with individuals, families and communities, promoting social change and addressing injustice across various professional contexts. Upon completion, you’ll be eligible for membership with the Australian Association of Social Workers (AASW), opening doors to professional practice in Australia and beyond.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 71520,
    apply_form = 'https://www.cqu.edu.au/courses/cl90/master-of-social-work-qualifying',
