UPDATE courses SET
    course_description = '<p>The Bachelor of Creative Media at CQU provides advanced preparation for a range of professional roles in the design, technology and media industries.</p><p>Tailor your studies to suit your individual strengths and interests, with a choice of majors and minors in:</p><p>Learn more about each major and minor in the Structure &amp; Availability section below.</p><p>You will learn how to create digital media works using industry-standard software tools and techniques, whilst also learning to think critically, solve problems, communicate effectively, and work independently and collaboratively as part of a multidisciplinary team. You will engage with clients on real-world projects through work-integrated learning opportunities, either via individual work placements or collaborative team-based projects.</p><p>This course is an ideal option if you have already completed CQU’s <a href="/courses/cm99/diploma-of-animation">Diploma of Animation</a>, <a href="/courses/cm96/diploma-of-creative-media">Diploma of Creative Media</a>, <a href="/courses/co01/diploma-of-graphic-design">Diploma of Graphic Design</a>, <a href="/courses/cm97/diploma-of-interactive-media">Diploma of Interactive Media</a> or <a href="/courses/cm98/diploma-of-screen-production">Diploma of Screen Production</a>, with the option to secure credit for eight units included in the Bachelor of Creative Media. </p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 107640,
    apply_form = 'https://www.cqu.edu.au/courses/cm95/bachelor-of-creative-media',
    updated_at = NOW()
WHERE cricos_course_code = '081701M';
