UPDATE courses SET
    course_description = '<p>The Study Abroad (CQUGlobal Inbound Program) allows you to undertake vocational, undergraduate or postgraduate units at CQUniversity from any available discipline area and receive credit towards your home award (if applicable); it is aimed at students currently enrolled in a vocational qualification or a bachelor or master degree level course overseas, or those with some previous study at these levels with an interest in an international study experience. </p><p>You can choose units or subjects and combine them to design a personalised course that meets your academic and personal goals. Alternatively, you can utilise elective subjects in your home course to study an area outside of your major that interests you. You can choose internal (face-to-face) units from any CQU study area subject to availability at your desired campus and recognising that some units have prerequisites that you would need to meet before enrolling in this course. The Study Abroad (CQUGlobal Inbound Program) is available for students to enrol in one and two terms of study. </p><p>You can enrol in Study Abroad (CQUGlobal Inbound Program) at Brisbane, Mackay or Rockhampton campuses, depending on unit availability. For more information see visit our <a href="https://www.cqu.edu.au/about-us/locations">Campus Locations page</a>.</p><p>Rockhampton in Central Queensland is the main campus of the University with on-site accommodation and the broadest range of units available.</p><p> The Study Abroad (CQUGlobal Inbound Program) allows you to undertake vocational, undergraduate or postgraduate units at CQUniversity from any available discipline area and receive credit towards your home award (if applicable); it is aimed at students currently enrolled in a vocational qualification or a bachelor or master degree level course overseas, or those with some previous study at these levels with an interest in an international study experience. You can choose units or subjects and combine them to design a personalised course that meets your academic and personal goals. Alternatively, you can utilise elective subjects in your home course to study an area outside of your major that interests you. You can choose internal (face-to-face) units from any CQU study areas subject to availability at your desired campus and recognising that some units have prerequisites that you would need to meet before enrolling in this course. The Study Abroad (CQUGlobal Inbound Program) is available for students to enrol in one and two terms of study. </p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 18720,
    apply_form = 'https://www.cqu.edu.au/courses/co57/study-abroad-cquglobal-inbound-program',
    updated_at = NOW()
WHERE cricos_course_code = '012078A';
UPDATE courses SET
    course_description = '<p>The Doctor of Education (EdD) is a doctoral course of supervised research and research tasks designed for professional practitioners/educators. The course comprises foundational coursework, proposal development and a thesis component.</p><p>The course is governed by the <a href="https://delivery-cqucontenthub.stylelabs.cloud/api/public/content/research-higher-degree-course-rules.pdf">Research Higher Degree Course Rules</a> which provide details regarding all aspects of admission, progression, submission and examination of your thesis.</p><p>Interested in speaking to someone about the Doctor of Education? <a href="/research/research-higher-degrees/ask-a-question">Book a call back today</a>.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 130944,
