UPDATE courses SET
    course_description = '<p>Kickstart your IT career with our Bachelor of Information Technology and benefit from real-world experience and the support of our experienced course leaders. Develop in-demand industry skills valued by employers through authentic learning experiences. </p><p>Within this highly practical degree, you''''ll develop a broad foundation of IT knowledge and skills, plus gain access to work-integrated learning opportunities that prepare you for a successful IT career. Designed with input from our industry partners, benefit from innovative, up-to-date and industry-relevant units, as well as in-built practical experiences.</p><p>During your studies, your core units will provide you with a comprehensive understanding of key IT and computer-based systems areas. From your second term, you will begin to study units from your chosen major*:</p><p>Customise your studies further with a wide range of minors*, offering depth in complementary disciplines and aligning with emerging IT fields to align with your career aspirations. Minors include:</p><p>*Changes are expected to the majors and minors offered as part of this course from Term 1, 2027. Learn more about each major and minor, including upcoming changes in the Structure &amp; Availability section below. </p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 110160,
    onshore_tuition_fee = 34200,
    apply_form = 'https://www.cqu.edu.au/courses/cq18/bachelor-of-information-technology',
