UPDATE courses SET
    course_description = '<p>Study a Bachelor of Occupational Health and Safety and equip yourself with professional skills to enhance your employability.</p><p>Your studies will equip you with knowledge, attitudes, skills and initiatives in the safety science areas of occupational health and hygiene, ergonomics and human factors, accident investigation and occupational health and safety management. </p><p>You can tailor your studies to suit your interests and career aspirations, with a choice of minor in: </p><p>Learn more about each minor in the Structure and Availability section below.</p><p>Throughout your studies, you''''ll complete units that are project-based and incorporate authentic industry-relevant assessment tasks. You''''ll also benefit from 120 hours of work placement, ensuring you graduate work-ready and able to facilitate, educate, problem solve, and promote health and safety at workplaces and in the community.</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 105840,
    onshore_tuition_fee = 31800,
    apply_form = 'https://www.cqu.edu.au/courses/cq26/bachelor-of-occupational-health-and-safety',
    updated_at = NOW()
