UPDATE courses SET
    course_description = '<p>This versatile dual business and accounting degree is a powerful combination for anyone interested in launching a career in business. As a professionally accredited accounting degree, you will be well prepared to lead financially viable organisations in an increasingly competitive commercial landscape. </p><p>Register for our <a href="/events/1279548/business-and-accounting-open-day-webinar">Business and Accounting Webinar</a> on Wednesday 26th August</p><p>The Bachelor of Accounting/Bachelor of Business gives you the opportunity to increase your employability by developing knowledge and skills in both accounting and business. Your education and training will include audit methodology and planning, and equip you with tools and techniques that financial managers use to maximise shareholder wealth.</p><p>In addition, you will gain exposure to accounting theory, accounting standards and business law relevant to the financial records of Australian companies.</p><p>While studying this dual degree you have the freedom to tailor your studies to suit your individual needs and career goals.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 140160,
    onshore_tuition_fee = 69600,
    apply_form = 'https://www.cqu.edu.au/courses/cq91/bachelor-of-accountingbachelor-of-business',
    updated_at = NOW()
